<body>
<div class="app">
  <h1>📝 Todo App</h1>
  <div class="input-row">
    <input id="todoInput" type="text" placeholder="What needs to be done?" autofocus>
    <button id="addBtn">Add</button>
  </div>
  <div class="filters">
    <button data-filter="all" class="active">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="completed">Completed</button>
  </div>
  <ul id="todoList"></ul>
</div>
<script>
(function() {
  const STORAGE_KEY = 'todo-app-data';
  let todos = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  let currentFilter = 'all';

  const input = document.getElementById('todoInput');
  const addBtn = document.getElementById('addBtn');
  const list = document.getElementById('todoList');
  const filterBtns = document.querySelectorAll('.filters button');

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function addTodo() {
    const text = input.value.trim();
    if (!text) return;
    todos.push({ id: Date.now(), text, done: false });
    input.value = '';
    save();
    render();
  }

  function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (todo) { todo.done = !todo.done; save(); render(); }
  }

  function deleteTodo(id) {
    todos = todos.filter(t => t.id !== id);
    save();
    render();
  }

  function getFiltered() {
    if (currentFilter === 'active') return todos.filter(t => !t.done);
    if (currentFilter === 'completed') return todos.filter(t => t.done);
    return todos;
  }

  function render() {
    const filtered = getFiltered();
    if (filtered.length === 0) {
      list.innerHTML = '<li class="empty">' +
        (todos.length === 0 ? 'No todos yet. Add one above!' : 'No matching todos.') +
        '</li>';
      return;
    }
    list.innerHTML = filtered.map(t => `
      <li class="${t.done ? 'done' : ''}">
        <span class="todo-text" onclick="window.__toggle(${t.id})">${escapeHtml(t.text)}</span>
        <button class="delete-btn" onclick="window.__delete(${t.id})" title="Delete">&times;</button>
      </li>
    `).join('');
  }

  function escapeHtml(s) {
    const d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  window.__toggle = toggleTodo;
  window.__delete = deleteTodo;

  addBtn.addEventListener('click', addTodo);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;
      render();
    });
  });

  render();
})();
</script>
</body>
